import datetime,hashlib,json,pathlib,subprocess,sys,time
root=pathlib.Path.cwd();out=root/'.work/m12-independent-operator';name=sys.argv[1];argv=sys.argv[2:];before={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in (root/'.work/m12-alpha').glob('*') if p.is_file()};start=time.monotonic();r=subprocess.run(argv,capture_output=True);(out/(name+'.stdout')).write_bytes(r.stdout);(out/(name+'.stderr')).write_bytes(r.stderr);after={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in (root/'.work/m12-alpha').glob('*') if p.is_file()};receipt={'name':name,'argv':argv,'cwd':str(root),'observed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'exit':r.returncode,'elapsed_seconds':time.monotonic()-start,'stdout_sha256':hashlib.sha256(r.stdout).hexdigest(),'stderr_sha256':hashlib.sha256(r.stderr).hexdigest(),'before_work_sha256':before,'after_work_sha256':after};(out/(name+'.receipt.json')).write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt));print(r.stdout.decode(errors='replace')[:5000]);print(r.stderr.decode(errors='replace')[:4000],file=sys.stderr)
